					uni.redirectTo({
						url: '/pages/login/login'
					})
				}
			} catch (error) {
				console.error('登录状态检查失败:', error)
			}
		},

		switchTab(tab) {
			this.activeTab = tab
			// 这里可以根据tab切换加载不同的数据
			this.loadCircleList()
		},

		loadCircleList() {
			// 根据activeTab加载对应的圈子列表
